-- Stage updated project knowledge as a pending review (do NOT touch content directly).
-- The diff will appear in /knowledge for the user to approve or reject.
UPDATE public.knowledge_documents
SET
  pending_content = convert_from(decode('', 'base64'), 'UTF8'),
  pending_summary = 'Backfill missing architecture: new edge functions (backfill-intercom-replies, promote-pending-intercom-links, poll-intercom-inbox, etc.), new tables (conversation_audit_logs, pending_intercom_links), new DB function search_conversations, /login and /my/:owner routes, two-source internal notes model with manual_messages.is_internal_note, Slack-import auto-navigation, canonical owners list (Joel/Kristina/Sam/CSM/Eren/Tine), and the manual_messages dedup rule.',
  pending_at = now()
WHERE id = 'project-knowledge';
